{"content":"/**
 * Round 20 red probe: does the machine ledger name the supervisor chain?
 *
 * Run with: npx vitest run test/probe-round20-supervisor-ledger.spec.ts
 * This file is SCRATCH for the red demonstration only and is deleted before
 * the round lands; the landed guard lives in test/delivery.spec.ts.
 */
import { describe, expect, it } from 'vitest'
import { machineLedger } from '../src/delivery/index.js'
import { resolveConfig, FIXED_MAX_RETRIES } from '../src/config.js'
import { assertWorkflowReport } from '../src/report.js'
import { maxTotalAgentsFor, routeBudgetFor } from '../src/script.js'
import { execution, task, verification } from './fixtures.js'

const LIMITS = { maxConcurrency: 2, maxTasks: 4 } as const
const config = resolveConfig({
  ...LIMITS,
  roles: { supervisor: [{ provider: 'p1', model: 'm-sv' }] },
})
const OBJECTIVE = 'probe objective'

function reportWithSupervisorChain() {
  const planTask = task('a', ['done'])
  const checked = verification(planTask)
  return assertWorkflowReport({
    schemaVersion: 'grok-workflow/v1',
    status: 'completed',
    objective: OBJECTIVE,
    plan: { source: 'caller', tasks: [planTask], error: '' },
    tasks: [{
      ...planTask,
      status: 'verified',
      attempts: [{ attempt: 1, execution: execution('did it'), verification: checked, passed: true, error: '' }],
      error: '',
    }],
    confirmed: [{ taskId: 'a', criterion: 'done', evidence: checked.criteria[0]!.evidence }],
    incomplete: [],
    errors: [],
    uncertainties: [],
    routing: {
      planner: [],
      worker: [],
      verifier: [],
      supervisor: ['p1/m-sv'],
      synthesizer: [],
    },
    routes: [],
    synthesis: { mode: 'deterministic', summary: 'did it.' },
    limits: { ...LIMITS, maxRetries: 1, maxTotalAgents: maxTotalAgentsFor(1, FIXED_MAX_RETRIES, routeBudgetFor(config)) },
  }, OBJECTIVE, config)
}

describe('round-20 red probe (scratch)', () => {
  it('ledger names the supervisor chain', () => {
    const ledger = machineLedger(reportWithSupervisorChain())
    expect(ledger).toContain('supervisor=p1/m-sv')
  })
})
