export function relayText(report: WorkflowReport, header?: string, opts?: RelayOptions): string {
  const preamble = report.status === 'failed' ? FAILURE_PREAMBLE : SUCCESS_PREAMBLE
  const lang: DeliveryLang = opts?.lang === 'en' ? 'en' : 'zh'
