import("./lib/redact.js").then(({redactSecrets}) => {
  const pem = "-----BEGIN PRIVATE KEY-----\nMIIEvQIBADANBgkqhkfakeKEYBODY\n-----END PRIVATE KEY-----\n";
  const blob = Buffer.from(pem, "utf8").toString("base64");
  for (const w of [7, 8, 12, 16, 19, 20, 21, 22, 23, 24]) {
    const folded = blob.replace(new RegExp(".{" + w + "}", "g"), "$&\n").trimEnd();
    const out = redactSecrets("dump:\n" + folded + "\nend marker here");
    const redacted = out.includes("[REDACTED PRIVATE KEY]");
    const leftover = (out.match(/[A-Za-z0-9+/]{20,}/g) || []).length;
    console.log("w=" + w, redacted ? "REDACTED" : "LEAK", "leftover20+:" + leftover);
  }
});
'","description":"Reproduce fold-width behavior on HEAD"}

